-- Replace generic coastal rhythm and activity boilerplate with place-specific lore.
-- Guarded against overwriting later editorial changes or private locations.
with edits(slug, rhythm, notes, facts) as (
  values
    ('admiralty-quay', '{"morning":"First ferries unload beside the handcarts.","afternoon":"Cargo and passenger queues compete for the quay.","evening":"Departing crews look for the last boat home.","late_night":"The lamps stay on for watchmen and late arrivals."}'::jsonb, '{"Walk the public quay":"Public streets welcome visitors; individual venues keep their own hours and rules.","Follow the ferry bells":"Watch the landing crews signal each arriving ferry.","Watch crews load cargo":"Public streets welcome visitors; individual venues keep their own hours and rules."}'::jsonb, '["The working arrival edge of Tidemark, where law, labor, and departures share a narrow waterfront."]'::jsonb),
    ('arrival-steps', '{"morning":"The first bell brings wet boots and breakfast parcels ashore.","afternoon":"Families wait above the freight lane for arriving ferries.","evening":"Passengers hurry toward the last scheduled crossings.","late_night":"A watchman keeps the steps clear for an unscheduled landing."}'::jsonb, '{"meeting arrivals":"Do not block the freight lane; private reunions take the upper landing.","watching ships":"Do not block the freight lane; private reunions take the upper landing.","Read the arrival board":"Check the chalk board for the next ferry and its passengers."}'::jsonb, '["The steps were widened after the Year 62 storm; older residents still remember helping carry people ashore."]'::jsonb),
    ('customs-house', '{"morning":"Clerks break seals and sort the overnight manifests.","afternoon":"Captains wait at the scarred counters for cargo clearance.","evening":"The last papers are stamped before the public hall closes.","late_night":"The counters are shut; sealed cargo stays under guard."}'::jsonb, '{"customs inquiry":"Declare cargo before asking favors; official records are not private gossip.","paperwork":"Declare cargo before asking favors; official records are not private gossip.","Check a cargo seal":"Ask a clerk to verify a public cargo seal at the counter."}'::jsonb, '["A false manifest once caused the port to quarantine a harmless spice cargo for a week."]'::jsonb),
    ('brass-compass', '{"morning":"Night crews take breakfast in the quieter half of the room.","afternoon":"Tables fill with sailors eating between sailings.","evening":"Music and overdue conversations claim the back table.","late_night":"The staff settle tabs before the final patrons leave."}'::jsonb, '{"breakfast":"The back table belongs to no rank; settle a tab before boarding.","drinks":"The back table belongs to no rank; settle a tab before boarding.","listening to music":"The back table belongs to no rank; settle a tab before boarding.","Take the back table":"Settle in at the quiet table after the breakfast rush."}'::jsonb, '["The tavern sheltered crews when the old breakwater failed."]'::jsonb),
    ('ferry-hall', '{"morning":"Commuters check the tide clock against the first sailings.","afternoon":"Weather changes can turn a short wait into a full room.","evening":"Travelers watch for the last ferry and make backup plans.","late_night":"The hall closes after the final crossing; missed passengers wait elsewhere."}'::jsonb, '{"waiting for ferry":"A departure board is a forecast, not a promise in bad weather.","planning a crossing":"A departure board is a forecast, not a promise in bad weather.","Check the tide clock":"Compare the posted ferry time with the tide clock."}'::jsonb, '["The hall’s carved bench names mark ferries lost in the Year 62 storm."]'::jsonb),
    ('sailors-exchange', '{"morning":"Work slips go up while crews look for hands.","afternoon":"Gear trades and wage arguments crowd the canvas awning.","evening":"Captains take down their notices as the market thins.","late_night":"The exchange is closed; no new crew bargains are posted."}'::jsonb, '{"finding a crew":"Read the posted rate before accepting a private bargain.","trading gear":"Read the posted rate before accepting a private bargain.","Read the wage notices":"Compare the crew openings and posted pay rates."}'::jsonb, '["After convoy year, the Exchange began posting wage terms in public."]'::jsonb),
    ('harbor-court', '{"morning":"The clerk posts the day’s hearings outside the room.","afternoon":"Witnesses and claimants take turns before the raised desk.","evening":"A final ruling sends people back into the quay.","late_night":"The gallery is closed and sealed testimony stays inside."}'::jsonb, '{"attending a hearing":"The gallery may watch; witnesses do not discuss sealed testimony outside.","reading notices":"The gallery may watch; witnesses do not discuss sealed testimony outside.","Watch a public case":"Sit in the gallery for an open harbor hearing."}'::jsonb, '["The court has twice ruled against the Admiralty on worker pay."]'::jsonb),
    ('gilt-row', '{"morning":"Delivery carts cross the pale terraces before patrons wake.","afternoon":"Bankers, jewellers and messengers move between galleries.","evening":"Salon guests arrive while shop shutters come down.","late_night":"Carriages thin out; private balconies stay lit."}'::jsonb, '{"Walk the sea-facing terraces":"Public streets welcome visitors; individual venues keep their own hours and rules.","Browse the shop windows":"See what the jewellers and map sellers have on display.","Look for old harbor maps":"Public streets welcome visitors; individual venues keep their own hours and rules."}'::jsonb, '["Terraces, lenders, jewellers, and salons look over the same harbor that supplies their wealth."]'::jsonb),
    ('pearl-salon', '{"morning":"The room is shut while musicians prepare elsewhere.","afternoon":"Staff tune the piano and set the terrace for guests.","evening":"Performers and patrons meet under the pearl lamps.","late_night":"The last debates continue until the salon closes."}'::jsonb, '{"listening to music":"An invitation admits a guest; it does not purchase their agreement.","Join a salon debate":"Take a side in the discussion after the music.","dancing":"An invitation admits a guest; it does not purchase their agreement."}'::jsonb, '["Sabine Quill opened the salon to performers after a bank-sponsored concert refused them credit."]'::jsonb),
    ('salt-ledger-bank', '{"morning":"Clerks reconcile ship accounts before the public doors open.","afternoon":"Repayment appointments make the counter unusually quiet.","evening":"Clients hurry to finish contracts before the bank shuts.","late_night":"The bank is closed; its ledgers are not available to visitors."}'::jsonb, '{"banking":"Do not expose another client’s debt across the counter.","reviewing contracts":"Do not expose another client’s debt across the counter.","Ask about a ship loan":"Discuss published loan terms at the public desk."}'::jsonb, '["The bank’s convoy-year collection is still argued about in Ropewalk kitchens."]'::jsonb),
    ('gilt-auction', '{"morning":"Porters uncover lots and check their condition.","afternoon":"Buyers inspect salvage and ask where it came from.","evening":"Bidding gathers pace under the chandeliers.","late_night":"The rooms close while unsold lots are secured."}'::jsonb, '{"viewing an auction":"Ask provenance before bidding on salvage.","bidding":"Ask provenance before bidding on salvage.","Inspect a lot":"Look over a map or cargo lot before the bidding starts."}'::jsonb, '["A seized ship’s bell once came up for sale and was returned after its crew protested."]'::jsonb),
    ('glass-garden', '{"morning":"Gardeners water the salt-tolerant vines.","afternoon":"Tea tables fill beside the basin.","evening":"The public path stays busy until the last light.","late_night":"The garden gates close; private dinners do not open the grounds."}'::jsonb, '{"garden walk":"Keep the public path open; private dinners use the side terrace.","tea":"Keep the public path open; private dinners use the side terrace.","Sit by the water basin":"Find a table beside the garden’s mosaic basin."}'::jsonb, '["The garden was a private terrace until its owner deeded a public path through it."]'::jsonb),
    ('velvet-balcony', '{"morning":"The balcony is dark while the company prepares.","afternoon":"Crew set lamps and check the curtains.","evening":"The audience can see the performers before the play begins.","late_night":"The final applause fades and the theatre closes."}'::jsonb, '{"watching a play":"Quiet during the scene; talk freely at intermission.","music":"Quiet during the scene; talk freely at intermission.","Talk at intermission":"Step onto the balcony while the cast resets the stage."}'::jsonb, '["A storm once forced a cast to finish a comedy by lantern in the audience aisle."]'::jsonb),
    ('montrose-jewels', '{"morning":"A jeweller sorts repairs at the bench.","afternoon":"Patrons examine stones with a craftsperson beside them.","evening":"Finished pieces are put away before the shop closes.","late_night":"The workshop is shut; no private workbench visits are offered."}'::jsonb, '{"browsing jewellery":"Handling a piece requires invitation, even when a patron can afford it.","craft lesson":"Handling a piece requires invitation, even when a patron can afford it.","Inspect a repaired piece":"Ask to see how a damaged sea find was set without hiding its cracks."}'::jsonb, '["Iria Montrose refused to recut a family stone whose crack carried its history."]'::jsonb),
    ('ropewalk', '{"morning":"Shipwrights carry timber and canvas toward the yards.","afternoon":"Repair crews and apprentices share the narrow routes.","evening":"Workers head toward supper with sawdust still on their coats.","late_night":"A few homes and watch lamps remain lit beside quiet sheds."}'::jsonb, '{"Walk the repair sheds":"Public streets welcome visitors; individual venues keep their own hours and rules.","Watch rope being laid":"Follow the public edge of the sheds while crews twist new line.","Stop at the workers’ kitchen":"Public streets welcome visitors; individual venues keep their own hours and rules."}'::jsonb, '["The shipbuilding district is a place of skill, shared meals, labor politics, and constant repair."]'::jsonb),
    ('shipwright-yard', '{"morning":"Crews check hull ribs before lifting timber.","afternoon":"Saws and hammers carry across the open yard.","evening":"Tools are counted and fresh tar pots covered.","late_night":"The yard is closed; a moored hull is not a public walkway."}'::jsonb, '{"watching shipbuilding":"Visitors stay behind the marked beam line unless invited by the foreperson.","learning repairs":"Visitors stay behind the marked beam line unless invited by the foreperson.","Study a hull frame":"Watch the builders fit ribs from behind the marked beam line."}'::jsonb, '["Bruna Kest’s crew rebuilt two ferries after the Year 62 storm."]'::jsonb),
    ('sail-loft', '{"morning":"Cutters lay out canvas in daylight.","afternoon":"Stitchers compare patterns at the long tables.","evening":"Finished sails are rolled before the loft closes.","late_night":"The loft is shut and its laid-out work stays untouched."}'::jsonb, '{"sewing sails":"Never step on laid-out canvas in work boots.","craft lesson":"Never step on laid-out canvas in work boots.","Examine a patched sail":"Ask a sailmaker about the old teaching piece in the loft."}'::jsonb, '["The loft still keeps a patched sail from the convoy year as a teaching piece."]'::jsonb),
    ('ropewalk-kitchen', '{"morning":"Early crews take soup before their shifts.","afternoon":"Neighbors share the long table between jobs.","evening":"Two supper pots feed workers coming off different shifts.","late_night":"The hearth cools after the last dishes are washed."}'::jsonb, '{"eating together":"A seat is offered before a person is asked why they need it.","cooking":"A seat is offered before a person is asked why they need it.","Help serve supper":"Carry bowls to the long table when the shift changes."}'::jsonb, '["Celia Mar organized the kitchen when wages were delayed one storm season."]'::jsonb),
    ('drydock-baths', '{"morning":"The quiet pools take the earliest workers.","afternoon":"Crews choose between social and silent rooms.","evening":"Shift changes bring a second rush to the baths.","late_night":"Screens close and the pools are cleaned for morning."}'::jsonb, '{"bathing":"Ask before joining a quiet room or discussing someone’s work there.","relaxing":"Ask before joining a quiet room or discussing someone’s work there.","Choose a quiet room":"Take a break in the separate quiet bathing room."}'::jsonb, '["The baths were built with dockworkers’ pooled wages rather than a patron’s gift."]'::jsonb),
    ('rivet-school', '{"morning":"Instructors set out fittings for the first lesson.","afternoon":"Apprentices practice knots and measurements at the rig.","evening":"Adults changing trades finish the last demonstrations.","late_night":"The training hall is closed and practice rigs are secured."}'::jsonb, '{"learning seamanship":"Demonstrations require an instructor; practice rigs are not toys.","ropework":"Demonstrations require an instructor; practice rigs are not toys.","Try a practice knot":"Learn a knot on the practice rig with an instructor."}'::jsonb, '["The school now admits adults changing trades after a public dispute over age limits."]'::jsonb),
    ('lantern-foundry', '{"morning":"The furnace warms while brass molds are prepared.","afternoon":"Glass and metalwork move between hot and cool benches.","evening":"Workers leave new signal lamps on the racks.","late_night":"The foundry is shut; cooling work is left alone."}'::jsonb, '{"watching metalwork":"Watch from the cool side of the line; hot work is not a performance.","craft lesson":"Watch from the cool side of the line; hot work is not a performance.","Compare signal lamps":"Look at finished lamps from the cool side of the workshop."}'::jsonb, '["A foundry-made lamp guided a ferry in after the lighthouse glass cracked."]'::jsonb),
    ('lantern-market', '{"morning":"Stallholders unload food and sweep the courtyards.","afternoon":"Awnings rise as the first vendors begin serving.","evening":"Oil lanterns bring the densest crowd into the lanes.","late_night":"Music and food linger until the last stalls close."}'::jsonb, '{"Explore the evening lane":"Public streets welcome visitors; individual venues keep their own hours and rules.","Follow the food stalls":"Walk the evening lane and choose what to eat.","Listen for the street musicians":"Public streets welcome visitors; individual venues keep their own hours and rules."}'::jsonb, '["The crowded evening heart of Tidemark, where food, performance, pleasure, and neighborhood business overlap."]'::jsonb),
    ('night-market', '{"morning":"The lane is mostly preparation and deliveries.","afternoon":"Cooks light stoves as the first stalls open.","evening":"Shoppers move between food, cloth and chart sellers.","late_night":"Vendors pack the final stalls and extinguish lanterns."}'::jsonb, '{"market tasting":"Stallholders set their own prices; bargaining is conversation, not entitlement.","shopping":"Stallholders set their own prices; bargaining is conversation, not entitlement.","Browse the chart stall":"Look over the maps sold between the food and cloth stands."}'::jsonb, '["The market moved uphill after the Year 62 surge and never moved back."]'::jsonb),
    ('honeyglass-theatre', '{"morning":"The theatre is quiet while the cast rehearses.","afternoon":"Crew paint shutters and test the glass lamps.","evening":"Dancers and storytellers play to a close audience.","late_night":"The last performance ends and the benches empty."}'::jsonb, '{"watching a show":"Do not assume a performer is available after the show.","dancing":"Do not assume a performer is available after the show.","music":"Do not assume a performer is available after the show."}'::jsonb, '["A canceled opening night became an annual amateur performance."]'::jsonb),
    ('house-of-hours', '{"morning":"The public tea room is closed while staff rest.","afternoon":"Workers prepare the tea room and agree on the shift.","evening":"Guests may enter the public room; private access remains by invitation.","late_night":"The tea room closes after the final guests leave."}'::jsonb, '{"tea":"Adults only. Entry to the tea room grants no access to private rooms; every service is separately chosen.","Read the house rules":"Learn the worker-run house’s boundaries in the public tea room.","adult companionship":"Adults only. Entry to the tea room grants no access to private rooms; every service is separately chosen."}'::jsonb, '["The staff bought their lease together in Year 86 and keep a public record of house rules."]'::jsonb),
    ('mariners-table', '{"morning":"Cooks prepare fish and herbs before lunch.","afternoon":"Market workers take the long table in turns.","evening":"Captains and fishers argue over the last bowl of stew.","late_night":"The kitchen closes after the final meal."}'::jsonb, '{"dinner":"The long table takes late arrivals before reserved tables do.","cooking":"The long table takes late arrivals before reserved tables do.","Share the last stew":"Join the long table while the kitchen still has stew."}'::jsonb, '["Javier Ro kept serving soup on credit when the payment scale failed one season."]'::jsonb),
    ('blue-lantern-inn', '{"morning":"Breakfast guests cross the courtyard to the front desk.","afternoon":"The desk welcomes ferries’ arrivals and keeps guest rooms private.","evening":"Late travelers ask for rooms without having to explain why.","late_night":"A lamp stays on at the desk for people arriving after midnight."}'::jsonb, '{"lodging":"Discretion protects guests, but staff will seek help when someone is in danger.","breakfast":"Discretion protects guests, but staff will seek help when someone is in danger.","Rest in the courtyard":"Take a quiet break beside the inn’s courtyard well."}'::jsonb, '["The inn housed ferry passengers for three nights during a squall."]'::jsonb),
    ('spice-courtyard', '{"morning":"The arcade is quiet before the food sellers arrive.","afternoon":"Chess boards and food counters claim the shaded corners.","evening":"Small music sets draw neighbors past the fountain.","late_night":"Players finish their games before the courtyard vendors close."}'::jsonb, '{"street food":"Leave a game open for the next person when the market closes.","games":"Leave a game open for the next person when the market closes.","music":"Leave a game open for the next person when the market closes.","Join a chess game":"Take an open board when the evening players gather."}'::jsonb, '["Neighbors repaired the courtyard fountain after a merchant asked to enclose it."]'::jsonb),
    ('breakwater-point', '{"morning":"Guards and healers take over from the night watch.","afternoon":"Visitors walk the seawall beside working stations.","evening":"Storm watchers compare the horizon with the tide charts.","late_night":"The public path stays exposed while working rooms close."}'::jsonb, '{"Walk the sea wall":"Keep to the public path above the outer surf.","Watch the fort drill":"Public streets welcome visitors; individual venues keep their own hours and rules.","Climb the public lighthouse stair":"Public streets welcome visitors; individual venues keep their own hours and rules."}'::jsonb, '["Storm watchers, healers, and guards work where the harbor meets open water."]'::jsonb),
    ('lightkeep', '{"morning":"The keeper checks the lamp before visitors climb.","afternoon":"The public viewing stair opens beneath the working lens.","evening":"Visitors leave before the keeper prepares the night signal.","late_night":"The lamp works through the night; its room is not public."}'::jsonb, '{"lighthouse climb":"The lamp room is restricted while the public viewing stair is open.","watching the sea":"The lamp room is restricted while the public viewing stair is open.","View the old lens":"See the lighthouse lens from the public stair."}'::jsonb, '["A replacement lens was fitted by hand after the Year 62 storm."]'::jsonb),
    ('storm-clinic', '{"morning":"Staff change the linen and replenish rescue blankets.","afternoon":"Patients arrive with cuts, seasickness and lost sleep.","evening":"The next shift takes over as boats return.","late_night":"Emergency care remains available while social visits wait."}'::jsonb, '{"medical care":"Patient details are private; emergencies take priority over social visits.","visiting":"Patient details are private; emergencies take priority over social visits.","Bring dry blankets":"Ask staff if the rescue blanket shelf needs restocking."}'::jsonb, '["The clinic grew from a rescue station and still keeps a dry blanket shelf by the door."]'::jsonb),
    ('battery-yard', '{"morning":"Guards clear the public path before drills.","afternoon":"Visitors watch from behind the powder line.","evening":"Crews secure practice equipment as the fort closes.","late_night":"The yard is closed to visitors under the night watch."}'::jsonb, '{"watching drills":"The public path ends at the powder line.","history walk":"The public path ends at the powder line.","Watch the warning drill":"Observe the fort crew from the public side of the powder line."}'::jsonb, '["The fort fired warning shots during the Year 91 cutter confrontation."]'::jsonb),
    ('tide-observatory', '{"morning":"Observers record the first wind and tide readings.","afternoon":"Visitors compare charts with the sea outside.","evening":"The last measurements go into the handwritten log.","late_night":"The station closes; weather instruments keep working."}'::jsonb, '{"weather watching":"Ask before touching instruments; a single reading is not a forecast.","chart lesson":"Ask before touching instruments; a single reading is not a forecast.","Compare tide records":"Read today’s tide marks beside the storm-year record."}'::jsonb, '["Oren Gale keeps the storm-year readings beside current records so mistakes can be compared."]'::jsonb),
    ('breakwater-steps', '{"morning":"Walkers climb above the spray to read the memorial.","afternoon":"People watch ferries from the upper stone.","evening":"Departures draw a small sunset crowd.","late_night":"The steps remain public, but waves can make them dangerous."}'::jsonb, '{"seaside walk":"The memorial edge is kept clear even during festivals.","watching ships":"The memorial edge is kept clear even during festivals.","Read the storm memorial":"Pause at the names cut into the upper stone."}'::jsonb, '["Names of the missing from the Year 62 storm are cut into the upper stone."]'::jsonb),
    ('signal-house', '{"morning":"Signal crews check flags and sightlines.","afternoon":"Messages pass between quay and outer water.","evening":"The last public updates are posted before closing.","late_night":"Only the working watch remains inside."}'::jsonb, '{"signal-flag lesson":"Never raise a signal for amusement.","watching arrivals":"Never raise a signal for amusement.","Learn the warning flags":"Ask which flag warns ships away from the reef."}'::jsonb, '["A faded flag pattern once confused two ferries; the house now checks every replacement in daylight."]'::jsonb),
    ('outer-cays', '{"morning":"Small boats leave the fishing houses before the heat.","afternoon":"Residents unload catches and tend shared wells.","evening":"Visitors hurry back before the uncertain final ferry.","late_night":"Homes and anchored boats hold their own quiet lights."}'::jsonb, '{"Visit an island landing":"Public streets welcome visitors; individual venues keep their own hours and rules.","Find the public ferry":"Check which island landing has a return crossing today.","Ask about the return tide":"Public streets welcome visitors; individual venues keep their own hours and rules."}'::jsonb, '["Nearby islands and reefs depend on Tidemark but keep their own schedules, councils, and loyalties."]'::jsonb),
    ('reef-landing', '{"morning":"Fish baskets come off the first island boats.","afternoon":"Visitors ask residents about the changing return tide.","evening":"People gather for the last likely ferry.","late_night":"The landing is closed to routine crossings after dark."}'::jsonb, '{"arriving by ferry":"Ask before loading a stranger’s boat; island cargo has its own order.","fishing":"Ask before loading a stranger’s boat; island cargo has its own order.","Check the last return":"Ask when the tide will allow the ferry back to Tidemark."}'::jsonb, '["Cay residents rebuilt the pier themselves after a city contractor abandoned it."]'::jsonb),
    ('coconut-beach', '{"morning":"The marked shallows fill with early swimmers.","afternoon":"Picnics spread beneath the woven shade.","evening":"Families pack before the light goes from the water.","late_night":"The beach closes to routine visits after dark."}'::jsonb, '{"swimming":"Carry back what you bring; a beach fire uses the marked hearth.","picnic":"Carry back what you bring; a beach fire uses the marked hearth.","beach walk":"Carry back what you bring; a beach fire uses the marked hearth."}'::jsonb, '["The beach remains public under a council agreement despite repeated private bids."]'::jsonb),
    ('tidepool-cove', '{"morning":"Low tide reveals pools and tiny crabs.","afternoon":"Children and researchers share the protected shore.","evening":"Visitors leave as water rises over the rocks.","late_night":"The cove closes to routine visits after dark."}'::jsonb, '{"tidepool walk":"Observe living creatures where they are; follow the posted tide line.","drawing":"Observe living creatures where they are; follow the posted tide line.","Watch the crabs":"Look for small crabs without disturbing the protected pools."}'::jsonb, '["The council marked a no-take stretch after a season of souvenir collecting."]'::jsonb),
    ('windward-village', '{"morning":"Fishers mend nets beside the shared well.","afternoon":"Neighbors cross the windy square with supplies.","evening":"Families bring supper inside as boats return.","late_night":"Most doors close while a few harbor lamps remain."}'::jsonb, '{"village visit":"Visitors are welcome at the square; household doors remain private.","net mending":"Visitors are welcome at the square; household doors remain private.","Visit the village square":"Stop at the public square between the net sheds and well."}'::jsonb, '["The village negotiated its own ferry schedule after losing a market day to city priorities."]'::jsonb),
    ('blackfin-anchorage', '{"morning":"Captains inspect the moorings before repairs.","afternoon":"The public edge of the dock fills with hull work.","evening":"Crews secure tools and return to their boats.","late_night":"The repair dock is closed to casual visitors."}'::jsonb, '{"watching ships":"Do not assume a moored ship is open to board.","boat repair":"Do not assume a moored ship is open to board.","Walk the repair dock":"Watch hull repairs from the public section of the small dock."}'::jsonb, '["The cove sheltered families during the Year 91 confrontation."]'::jsonb),
    ('sable-reef', '{"morning":"Pilots check the channel markers before setting out.","afternoon":"Qualified crews cross the shallows with changing tide.","evening":"Boats leave the reef before the light fails.","late_night":"The reef is closed to routine visits after dark."}'::jsonb, '{"reef sail":"Go with a qualified pilot; the safe channel shifts after storms.","snorkeling":"Go with a qualified pilot; the safe channel shifts after storms.","chart lesson":"Go with a qualified pilot; the safe channel shifts after storms."}'::jsonb, '["An old wreck appears at the lowest tides, prompting repeated salvage claims."]'::jsonb)
)
update public.together_locations l
set canonical_lore = jsonb_set(jsonb_set(jsonb_set(jsonb_set(
    coalesce(l.canonical_lore, '{}'::jsonb),
    '{crowdRhythm}', e.rhythm, true),
    '{activityNotes}', e.notes, true),
    '{stableFacts}', e.facts, true),
    '{recurringPeople}', '[]'::jsonb, true),
    updated_at = now()
from edits e
join public.together_worlds w on w.slug = 'gilded-coast'
where l.world_id = w.id and l.slug = e.slug
  and l.owner_user_id is null and l.archived_at is null
  and l.canonical_lore->'crowdRhythm'->>'morning' = 'Crews and neighbors establish the practical day.';
